    static Object stateValue(ServerMatch m,UUID p,String name){try{var f=ServerMatch.class.getDeclaredField("players");f.setAccessible(true);var state=((Map<?,?>)f.get(m)).get(p);var v=state.getClass().getDeclaredField(name);v.setAccessible(true);return v.get(state);}catch(ReflectiveOperationException e){throw new AssertionError(e);}}
