    static CardDefinition synthetic(String id,CardCategory cat,TrainerCategory trainer,boolean basic){return new CardDefinition(id,id,cat,trainer,"J",Set.of("international"),basic,cat==CardCategory.ENERGY,60,Map.of(),EffectSupport.SUPPORTED,null,id.equals("rulebox")?Set.of(PokemonFamily.EX,PokemonFamily.RULE_BOX):Set.of(),cat==CardCategory.POKEMON?Set.of(EnergyType.COLORLESS):Set.of());}
