        for(String id:List.of("psychic","wrong"))defs.add(synthetic(id,CardCategory.ENERGY,TrainerCategory.NONE,false));
        for(String id:List.of("item","fossil","other","echo"))defs.add(synthetic(id,CardCategory.TRAINER,id.equals("other")?TrainerCategory.SUPPORTER:TrainerCategory.ITEM,false));
        var attacks=List.of(GeneratedRuleBatch8Test.hit(10,false),CopyAttackTest.copier());
