        for(String id:List.of("plain","evolved","rulebox"))profiles.put(id,new PokemonProfile(1000,1,id.equals("evolved")?"plain":null,null,0,null,0,id.equals("rulebox")?2:1,attacks,List.of(),EnergyType.COLORLESS));
