        var trainers=Map.of(EMMA,actualEmma,ALT,DATA.trainer(ALT).orElseThrow(),"item",ComposedTrainerIntegrationTest.item("{\"type\":\"draw\",\"amount\":1}"),"other",other,"echo",echo,"fossil",FossilFormTest.fossil());
        var catalog=new CombatCatalog(profiles,Map.of("psychic",EnergyType.PSYCHIC,"wrong",EnergyType.FIRE),trainers);
        String[] pool={ESPURR,ESPURR,"plain","plain","plain",EMMA,EMMA,ALT,ALT,"psychic","psychic","wrong","evolved","rulebox","item","fossil","other","echo"};
        String af=mode.equals("NORMAL")?ESPURR:"plain",bf=mode.equals("COPY")?ESPURR:"plain";
        for(int seed=0;seed<4000;seed++){var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var cs=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cs.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,pool[i%pool.length]));decks.add(cs);}var m=new ServerMatch(A,B,decks.getFirst(),decks.getLast(),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),catalog,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);
            if(m.privateView(A).hand().stream().filter(c->c.definitionId().equals(af)).count()<(af.equals("plain")?2:1)||m.privateView(A).hand().stream().noneMatch(c->c.definitionId().equals("plain"))||m.privateView(B).hand().stream().filter(c->c.definitionId().equals(bf)).count()<(bf.equals("plain")?2:1)||m.privateView(B).hand().stream().noneMatch(c->c.definitionId().equals("plain")))continue;
            m.chooseOpeningActive(A,hand(m,A,af).instanceId());m.placeOpeningBench(A,hand(m,A,"plain").instanceId());m.chooseOpeningActive(B,hand(m,B,bf).instanceId());m.placeOpeningBench(B,hand(m,B,"plain").instanceId());m.startAfterOpening(A);m.startAfterOpening(B);OpeningTestSupport.complete(m,A,B,0);m.drawCardsByEffect(A,A,24);m.drawCardsByEffect(A,B,24);m.endTurn(A);m.endTurn(B);
            if(List.of(A,B).stream().anyMatch(p->List.of(ESPURR,EMMA,ALT,"psychic","wrong","evolved","rulebox","item","fossil","other","echo").stream().anyMatch(id->m.privateView(p).hand().stream().noneMatch(c->c.definitionId().equals(id))))||m.privateView(B).hand().stream().filter(c->c.definitionId().equals("plain")).count()<2)continue;
            return m;
        }throw new AssertionError("No actual Emma/Espurr fixture "+mode);
