    static void attach(ServerMatch m,UUID owner,String id){var c=hand(m,owner,id);m.attachEnergyByEffect(m.currentPlayer(),owner,EffectSourceZone.HAND,c.instanceId(),owner,active(m,owner));}
    static List<CardInstance> exactHand(ServerMatch m,UUID owner,String... ids){var retain=new ArrayList<CardInstance>();for(String id:ids){var c=m.privateView(owner).hand().stream().filter(v->v.definitionId().equals(id)&&!retain.contains(v)).findFirst().orElseThrow(()->new AssertionError("Missing hand fixture "+id));retain.add(c);}var discard=m.privateView(owner).hand().stream().filter(c->!retain.contains(c)).map(CardInstance::instanceId).toList();if(!discard.isEmpty())m.discardHandCardsByEffect(m.currentPlayer(),owner,discard);return m.privateView(owner).hand();}
    static List<CardInstance> mixed(ServerMatch m){return exactHand(m,B,"plain","plain","evolved","rulebox","fossil","psychic","item",ALT);}
    static void finish(ServerMatch m,UUID actor){var r=m.effectCardReveal();check(r!=null&&r.confirmingPlayer().equals(actor),"Real Emma reveal missing");m.acknowledgeEffectReveal(actor,r.id());check(m.effectCardReveal()==null&&!m.hasPendingEffectChoice()&&m.currentPlayer().equals(actor),"Emma did not fully resume");}
    static void play(ServerMatch m,UUID actor,String id){m.playTrainer(actor,hand(m,actor,id).instanceId(),null);finish(m,actor);}
    static void damage(ServerMatch m,int expected){int old=m.activePokemonView(B).damage();m.attack(A,ATTACK);check(m.lastAttack().finalDamage()==expected&&m.activePokemonView(B).damage()==old+expected,"Buddy Attack expected "+expected);}
    static void assertPrivate(ServerMatch m,boolean revealed){var s=MatchSession.multiplayer(m,A,B);s.addSpectator(WATCH);for(UUID viewer:List.of(A,B,WATCH)){var v=s.view(viewer,viewer.equals(WATCH)?null:viewer);check((v.game().effectReveal()!=null)==revealed,"Reveal visibility state");String json=new Gson().toJson(v);for(UUID owner:List.of(A,B)){if(!viewer.equals(owner))for(var c:m.privateView(owner).hand())check(!json.contains(c.instanceId().toString()),"Reveal exposed hidden physical hand id");for(var c:m.privateView(owner).deck())check(!json.contains(c.instanceId().toString()),"Reveal exposed deck identity");}}}
    public static void main(String[]args){printed();bothEmmaAndReveal();zeroAndShortDeck();historyExclusions();lateEntry();copyController();independentTurns();System.out.println("GeneratedRuleBatch87Test passed: actual Espurr P10/70 and both real Emma, immutable mixed-hand physical Pokemon count including Evolution/rulebox/duplicates and Item Fossil exclusion, staged public-face-only reveal and authority/completion/quota, zero/short/empty own deck boundaries, exact completed own handplay history/reset/exclusions, late Espurr entry FAQ, actual controller copy and independent count memories");}
    static void printed(){var c=DB.find(ESPURR).orElseThrow();var p=DATA.pokemon(ESPURR).orElseThrow();check(c.effectSupport()==EffectSupport.SUPPORTED&&c.basicPokemon()&&p.hitPoints()==60&&p.pokemonType()==EnergyType.PSYCHIC&&p.weaknessType()==EnergyType.DARKNESS&&p.weaknessMultiplier()==2&&p.resistanceType()==EnergyType.FIGHTING&&p.resistanceAmount()==30&&p.retreatCost()==1&&p.prizeCards()==1&&p.abilities().isEmpty(),"Printed Espurr");var a=p.attacks().getFirst();check(p.attacks().size()==1&&a.id().equals(ATTACK)&&a.baseDamage()==10&&a.energyCost().equals(Map.of(EnergyType.PSYCHIC,1)),"Buddy Attack printed P10+");AttackProgramRules.validate(a);for(String id:List.of(EMMA,ALT)){check(DB.find(id).orElseThrow().effectSupport()==EffectSupport.SUPPORTED&&DB.find(id).orElseThrow().trainerCategory()==TrainerCategory.SUPPORTER&&DATA.trainer(id).orElseThrow().category()==TrainerCategory.SUPPORTER,"Actual Emma support/category "+id);TrainerProgramRules.validate(DATA.trainer(id).orElseThrow().effectProgram());}var m=game();atomic(m,()->m.attack(A,ATTACK));attach(m,A,"wrong");atomic(m,()->m.attack(A,ATTACK));attach(m,A,"psychic");damage(m,10);}
    static void bothEmmaAndReveal(){for(String id:List.of(EMMA,ALT)){var m=game();attach(m,A,"psychic");var opposing=mixed(m);var card=hand(m,A,id);var before=m.privateView(A);var rng=m.randomTranscript();check(m.canPlayTrainer(A,card.instanceId(),null),"Actual Emma not offered for public nonempty hand");m.playTrainer(A,card.instanceId(),null);var r=m.effectCardReveal();check(r!=null&&r.actor().equals(B)&&r.confirmingPlayer().equals(A)&&r.cardIds().equals(opposing.stream().map(CardInstance::definitionId).sorted().toList())&&opposing.stream().noneMatch(c->c.instanceId().equals(r.id())),"Exact public reveal faces/authority/opaque reveal id");check(m.privateView(B).hand().equals(opposing)&&m.privateView(A).deck().equals(before.deck())&&m.privateView(A).hand().size()==before.hand().size()-1&&!completed(m,A)&&quota(m,A)==0&&!m.privateView(A).discard().contains(card),"Emma drew/finished/history/quota before acknowledgement");assertPrivate(m,true);
            atomic(m,()->m.acknowledgeEffectReveal(B,r.id()));atomic(m,()->m.acknowledgeEffectReveal(WATCH,r.id()));atomic(m,()->m.acknowledgeEffectReveal(A,new UUID(99,99)));atomic(m,()->m.attack(A,ATTACK));atomic(m,()->m.endTurn(A));atomic(m,()->m.playTrainer(A,hand(m,A,id.equals(EMMA)?ALT:EMMA).instanceId(),null));
            m.acknowledgeEffectReveal(A,r.id());check(m.privateView(B).hand().equals(opposing)&&m.privateView(A).deck().equals(before.deck().subList(0,before.deck().size()-4))&&m.privateView(A).hand().size()==before.hand().size()+3&&m.privateView(A).discard().contains(card)&&completed(m,A)&&quota(m,A)==1&&m.randomTranscript().equals(rng),"Emma count should be4 physical Pokemon; Fossil Item must not count, no reorder/shuffle");assertPrivate(m,false);atomic(m,()->m.acknowledgeEffectReveal(A,r.id()));atomic(m,()->m.playTrainer(A,hand(m,A,id.equals(EMMA)?ALT:EMMA).instanceId(),null));damage(m,70);
        }}
    static void zeroAndShortDeck(){var zero=game();attach(zero,A,"psychic");exactHand(zero,B,"fossil","psychic","item");int before=zero.privateView(A).hand().size(),deck=zero.privateView(A).deck().size();play(zero,A,EMMA);check(zero.privateView(A).deck().size()==deck&&zero.privateView(A).hand().size()==before-1&&completed(zero,A)&&quota(zero,A)==1,"Nonempty zero-Pokemon reveal should draw0 and complete Emma");damage(zero,70);
        for(int remaining:List.of(0,1,2)){var m=game();attach(m,A,"psychic");mixed(m);int remove=m.privateView(A).deck().size()-remaining;if(remove>0)m.discardTopDeckCardsByEffect(A,A,remove);int hand=m.privateView(A).hand().size();check(m.canPlayTrainer(A,hand(m,A,EMMA).instanceId(),null),"Meaningful reveal disallowed by short/empty own deck");play(m,A,EMMA);check(m.privateView(A).deck().isEmpty()&&m.privateView(A).hand().size()==hand-1+remaining&&m.phase()==MatchPhase.TURN&&completed(m,A),"Short deck count, completion or immediate deckout");damage(m,70);check(m.phase()==MatchPhase.TURN&&m.currentPlayer().equals(B),"Empty deck caused early loss on attack");m.endTurn(B);check(m.phase()==MatchPhase.FINISHED&&m.clientView(A).result().reason()==MatchResult.Reason.DECK_OUT&&m.clientView(A).result().winner().equals(B),"Empty deck did not lose on next mandatory own draw");}
    }
    static void historyExclusions(){for(String mode:List.of("PRESENT","DISCARDED","DENIED","OTHER","OPPONENT","EXPIRED","ECHO")){var m=game();attach(m,A,"psychic");switch(mode){
            case "DISCARDED" -> m.discardHandCardsByEffect(A,A,List.of(hand(m,A,EMMA).instanceId(),hand(m,A,ALT).instanceId()));
            case "DENIED" -> {exactHand(m,B);var card=hand(m,A,EMMA);check(!m.canPlayTrainer(A,card.instanceId(),null),"Empty opponent hand offered no-effect Emma");atomic(m,()->m.playTrainer(A,card.instanceId(),null));check(quota(m,A)==0&&!completed(m,A),"Denied Emma consumed quota/history");m.playTrainer(A,hand(m,A,"other").instanceId(),null);check(quota(m,A)==1,"Denied Emma consumed later legal Supporter slot");}
            case "OTHER" -> m.playTrainer(A,hand(m,A,"other").instanceId(),null);
            case "OPPONENT" -> {m.endTurn(A);play(m,B,EMMA);m.endTurn(B);}
            case "EXPIRED" -> {play(m,A,EMMA);m.endTurn(A);m.endTurn(B);}
            case "ECHO" -> {mixed(m);play(m,A,"echo");check(quota(m,A)==0,"Synthetic effect-copy Item spent Supporter quota");}
        }check(!completed(m,A),"Non-Emma/current-own-completed hand play accepted: "+mode);damage(m,10);}}
    static void lateEntry(){for(String id:List.of(EMMA,ALT)){var m=game("LATE");check(m.benchPokemonView(A).stream().noneMatch(p->p.topCardId().equals(ESPURR))&&!m.activePokemonView(A).topCardId().equals(ESPURR),"Espurr was already in play");play(m,A,id);var card=hand(m,A,ESPURR);m.playBasicPokemonToBench(A,card.instanceId());UUID pokemon=PokemonIdentityTestSupport.logical(m,A,card.instanceId());m.switchActiveByEffect(A,A,pokemon);attach(m,A,"psychic");check(completed(m,A),"Player history lost when Espurr entered/switched");damage(m,70);}}
    static void copyController(){for(String mode:List.of("OWN","NONE","OPPONENT")){var m=game("COPY");attach(m,A,"wrong");if(mode.equals("OWN"))play(m,A,EMMA);if(mode.equals("OPPONENT")){m.endTurn(A);play(m,B,ALT);m.endTurn(B);}var o=m.copyAttackOptions(A,"copy").stream().filter(v->v.attackId().equals(ATTACK)).findFirst().orElseThrow();m.copyAttackWithEnergyDiscards(A,"copy",o.pokemonId(),o.entrySequence(),o.attackId(),List.of(),List.of());check(m.lastAttack().finalDamage()==(mode.equals("OWN")?70:10),"Copied Buddy Attack used donor history or wrong controller: "+mode);}}
    static void independentTurns(){var m=game();attach(m,A,"psychic");mixed(m);int h=m.privateView(A).hand().size();play(m,A,EMMA);check(m.privateView(A).hand().size()==h+3,"First Emma mixed count");m.endTurn(A);m.endTurn(B);check(!completed(m,A)&&quota(m,A)==0,"Turn history/quota did not reset");exactHand(m,B,"fossil","psychic","item");int deck=m.privateView(A).deck().size(),before=m.privateView(A).hand().size();play(m,A,ALT);check(m.privateView(A).deck().size()==deck&&m.privateView(A).hand().size()==before-1,"Second Emma inherited first reveal's count");damage(m,70);}
